def two_sum_sorted(nums, target):
    left, right = 0, len(nums) - 1
    while left < right:
        s = nums[left] + nums[right]
        if s == target:
            return [left, right]
        if s < target:
            left += 1
        else:
            right -= 1
    return []

# Example: two_sum_sorted([2,7,11,15], 9) -> [0, 1]
# Time: O(n), Space: O(1). One pass from both ends of the sorted array.

def remove_duplicates(nums):
    if not nums:
        return 0
    write = 1
    for read in range(1, len(nums)):
        if nums[read] != nums[write - 1]:
            nums[write] = nums[read]
            write += 1
    return write

# Example: nums=[0,0,1,1,1,2,2,3,3,4]; remove_duplicates(nums) -> 5, nums[:5] = [0,1,2,3,4]
# Time: O(n), Space: O(1). Fast/slow (read/write) two pointers.

def move_zeroes(nums):
    write = 0
    for num in nums:
        if num != 0:
            nums[write] = num
            write += 1
    while write < len(nums):
        nums[write] = 0
        write += 1
    return nums

# Example: move_zeroes([0,1,0,3,12]) -> [1,3,12,0,0]
# Time: O(n), Space: O(1). Partition non-zeros then backfill zeros.

def search_range(nums, target):
    def lower_bound(x):
        lo, hi = 0, len(nums)
        while lo < hi:
            mid = (lo + hi) // 2
            if nums[mid] < x:
                lo = mid + 1
            else:
                hi = mid
        return lo
    lo = lower_bound(target)
    hi = lower_bound(target + 1)
    if lo == hi:
        return [-1, -1]
    return [lo, hi - 1]

# Example: search_range([5,7,7,8,8,10], 8) -> [3,4]
# Time: O(log n), Space: O(1). Two binary-search lower bounds.

def merge(nums1, m, nums2, n):
    i, j, k = m - 1, n - 1, m + n - 1
    while i >= 0 and j >= 0:
        if nums1[i] >= nums2[j]:
            nums1[k] = nums1[i]
            i -= 1
        else:
            nums1[k] = nums2[j]
            j -= 1
        k -= 1
    while j >= 0:
        nums1[k] = nums2[j]
        j -= 1
        k -= 1

# Example: merge([1,2,3,0,0,0], 3, [2,5,6], 3) -> nums1 = [1,2,2,3,5,6]
# Time: O(m+n), Space: O(1). Merge from the back to avoid overwriting.

def search_matrix(matrix, target):
    if not matrix or not matrix[0]:
        return False
    m, n = len(matrix), len(matrix[0])
    lo, hi = 0, m * n - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        val = matrix[mid // n][mid % n]
        if val == target:
            return True
        if val < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return False

# Example: search_matrix([[1,3,5,7],[10,11,16,20],[23,30,34,60]], 3) -> True
# Time: O(log(m*n)), Space: O(1). Treat the 2D matrix as a virtual 1D sorted array.

def max_area(height):
    left, right = 0, len(height) - 1
    best = 0
    while left < right:
        area = min(height[left], height[right]) * (right - left)
        best = max(best, area)
        if height[left] < height[right]:
            left += 1
        else:
            right -= 1
    return best

# Example: max_area([1,8,6,2,5,4,8,3,7]) -> 49
# Time: O(n), Space: O(1). Two pointers shrink the narrower side.

def three_sum(nums):
    nums.sort()
    result = []
    n = len(nums)
    for i in range(n - 2):
        if i > 0 and nums[i] == nums[i-1]:
            continue
        if nums[i] > 0:
            break
        left, right = i + 1, n - 1
        while left < right:
            s = nums[i] + nums[left] + nums[right]
            if s == 0:
                result.append([nums[i], nums[left], nums[right]])
                left += 1
                right -= 1
                while left < right and nums[left] == nums[left-1]:
                    left += 1
                while left < right and nums[right] == nums[right+1]:
                    right -= 1
            elif s < 0:
                left += 1
            else:
                right -= 1
    return result

# Example: three_sum([-1,0,1,2,-1,-4]) -> [[-1,-1,2],[-1,0,1]]
# Time: O(n^2), Space: O(1) extra. Sort then two-pointer pairs for each anchor.

def longest_bitonic(nums):
    n = len(nums)
    if n == 0:
        return 0
    inc = [1] * n
    dec = [1] * n
    for i in range(1, n):
        for j in range(i):
            if nums[j] < nums[i]:
                inc[i] = max(inc[i], inc[j] + 1)
    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            if nums[j] < nums[i]:
                dec[i] = max(dec[i], dec[j] + 1)
    best = 0
    for i in range(n):
        best = max(best, inc[i] + dec[i] - 1)
    return best

# Example: longest_bitonic([1,11,2,10,4,5,2,1]) -> 6
# Time: O(n^2), Space: O(n). LIS from left + LIS from right combined at each peak.

def coin_change(coins, amount):
    INF = float('inf')
    dp = [0] + [INF] * amount
    for a in range(1, amount + 1):
        for c in coins:
            if c <= a and dp[a - c] != INF:
                dp[a] = min(dp[a], dp[a - c] + 1)
    return dp[amount] if dp[amount] != INF else -1

# Example: coin_change([1,2,5], 11) -> 3
# Time: O(amount * len(coins)), Space: O(amount). Bottom-up coin DP.

def search_insert(nums, target):
    lo, hi = 0, len(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo

# Example: search_insert([1,3,5,6], 5) -> 2; search_insert([1,3,5,6], 2) -> 1
# Time: O(log n), Space: O(1). Classic lower-bound binary search.

def merge_intervals(intervals):
    intervals.sort(key=lambda x: x[0])
    merged = [intervals[0]]
    for start, end in intervals[1:]:
        if start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])
    return merged

# Example: merge_intervals([[1,3],[2,6],[8,10],[15,18]]) -> [[1,6],[8,10],[15,18]]
# Time: O(n log n) for the sort, O(n) for the sweep. Space: O(n) for the output (O(1) extra beyond that).
